/// <inheritdoc />
public void Initialize(IncrementalGeneratorInitializationContext context)
{
    var calls = context.SyntaxProvider.CreateSyntaxProvider(
            static (node, _) => IsRegistrationSyntax(node),
            static (ctx, ct) => Analyze(ctx, ct))
        .Where(static call => call is not null)
        .Select(static (call, _) => call!)
        .WithTrackingName("PortiaRegistrationCalls")
        .Collect();
    var dispatchedRequests = context.SyntaxProvider.CreateSyntaxProvider(
            static (node, _) => node is InvocationExpressionSyntax
            {
                Expression: MemberAccessExpressionSyntax
                {
                    Name.Identifier.ValueText: "SendAsync" or "SendWithOutcomeAsync" or "StreamAsync" or "DispatchAsync"
                    or "DispatchStreamAsync"
                    or "EnqueueAsync" or "EnqueueWithOptionsAsync" or "PublishAsync" or "ScheduleAsync" or "EnsureAsync"
                    or "AddRequestSchedule"
                }
            },
            static (ctx, _) => DispatchedRequest(ctx))
        .Where(static request => request is not null)
        .Select(static (request, _) => request!)
        .Collect();
    // Events and JSON contexts are properties of the whole compilation, not of any one call
    // site. Reading them inside the per-call-site transform made every registration re-derive
    // the compilation and invalidated every call site whenever any event changed, so they get
    // their own per-node pipelines and are combined once, here.
    var jsonContexts = JsonContextDiscovery.DeclaredContexts(context);
    var referencedJsonContexts = JsonContextDiscovery.ReferencedContexts(context);
    var declaredEvents = DomainEventDiscovery.DeclaredEvents(context);
    var referencedEvents = DomainEventDiscovery.ReferencedEvents(context);
    var shared = jsonContexts.Combine(referencedJsonContexts).Combine(declaredEvents).Combine(referencedEvents)
        .Select(static (input, _) => SharedRegistrations(
            input.Left.Left.Left.AddRange(input.Left.Left.Right), input.Left.Right, input.Right))
        .WithTrackingName("PortiaSharedRegistrations");
    context.RegisterSourceOutput(calls, static (output, models) => ReportDiagnostics(output, models));
    var assemblyIdentity = context.CompilationProvider.Select(static (compilation, _) =>
        compilation.Assembly.Identity.ToString());
    var files = calls.Combine(dispatchedRequests).Combine(shared).Combine(assemblyIdentity)
        .SelectMany(static (pair, ct) => GeneratedSource.Capture(
            output => Generate(output, pair.Left.Left.Left, pair.Left.Left.Right, pair.Left.Right, pair.Right), ct))
        .WithTrackingName("PortiaRegistrationGeneratedFiles");
    context.RegisterSourceOutput(files, static (output, file) => GeneratedSource.Add(output, file.HintName, file.Source));
}

static bool IsRegistrationSyntax(SyntaxNode node) => node switch
{
    InvocationExpressionSyntax
    {
        Expression: MemberAccessExpressionSyntax { Name: { } name }
    } => IsRegistrationName(name),
    MemberAccessExpressionSyntax
    {
        Name: { } name, Parent: not InvocationExpressionSyntax
    } => IsRegistrationName(name),

